import{_ as e,o as t,c as a,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第三卷 潮汐 · 第57章 和好","description":"","frontmatter":{},"headers":[],"relativePath":"第57章_和好.md","filePath":"第57章_和好.md"}'),o={name:"第57章_和好.md"};function r(n,p,s,c,i,l){return t(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第三卷-潮汐-·-第57章-和好" tabindex="-1">第三卷 潮汐 · 第57章 和好 <a class="header-anchor" href="#第三卷-潮汐-·-第57章-和好" aria-label="Permalink to &quot;第三卷 潮汐 · 第57章 和好&quot;">​</a></h1><blockquote><p>【小注：本章为江苒视角】操场那二十圈，是她坐在场边一圈一圈数完的。接第56章。</p></blockquote><p>我抱着玻璃瓶坐在空教室里，瓶身凉意透进掌心，星星晃出细碎的响。林小满跑远了，走廊只剩落叶声。</p><p>我想立刻见到沈聿。</p><p>我把瓶子塞进怀里，往操场跑。风扑在脸上，湿凉，带着桂花落尽的甜和土腥，跑道味被雾泡得发闷。</p><p>远远的，我看见他了。</p><p>沈聿一个人在跑道上走，步子很慢，手插在兜里，头低着。夕阳被雾挡住，只剩一团白亮的光落在他肩上。陈默和顾远站在场边说话，看见我，互相推了一把，很有默契地走开了。顾远走前还把场边的旧磁带机抱走了，朝我晃了晃，笑得露出白牙。</p><p>场上一下空了，只剩我和他。</p><p>我站住，喉咙发紧，喊他的名字。声音撞进雾里，显得很小。</p><p>“沈聿。”</p><p>他抬头，看见我，愣了一下，随即站住等我。他的头发被雾打湿，发梢贴在额头，眼下有一圈淡青，像是没睡好。</p><p>我走到他面前，把玻璃瓶递过去，又收回来，抱得更紧。话在嘴边转了几圈，才挤出来。</p><p>“中午的事，林小满都跟我说了。我错怪你了，对不起。”</p><p>他看着我，没立刻说话。风把梧桐叶卷起来，擦着跑道滚过去，沙沙响。他的袖口沾着一点白，是粉笔灰，还是雾水凝成的霜，我看不清。</p><p>“你来得正好。”他忽然说，声音有点哑。“生气的时候，坐着说话容易吵起来。陪我走走吧。”</p><p>“走去哪。”</p><p>“绕操场，二十圈。”他踢了踢脚下的白线，嘴角动了动，想笑又没笑出来。“走得慢，话才能说全。走完还没说开，就再走。”</p><p>我点头，把玻璃瓶抱好，跟上他的步子。</p><p>第一圈，雾还浓。跑道湿滑，鞋底踩上去发出轻微的黏响。我的呼吸很快，带着跑过来的喘。他放慢步子等我，肩膀离我半步远，近到能闻到他外套上的洗衣粉香，混着一点海水的咸。</p><p>“那盘磁带，你还记得吗。”他先开口。</p><p>“记得。宋阿婆留下的那盘，你说里面有海浪。”</p><p>“那盘在我这里，好好的，谁也没给听。”他把手从兜里拿出来，指尖冻得发红。“中午那盘，是陈默托我转的。顾远发小的妹妹，就是那个新转来的同学，替她哥跑腿送来。我怕带子受潮转不动，当场试了一下。”</p><p>“我听林小满说了，一只耳机是坏的。”</p><p>“嗯。”他点头，呼出的白气散进雾里。“好的那只，我给她听了几秒，确认有海浪声就拔了。前后很短，没想到会被看见。”</p><p>第二圈过弯道，风大起来，叶堆在角落，踩上去发软，凉气渗进袜口。</p><p>我小声说：“她扶你那下，我看见了。”</p><p>“那里有水洼，她差点滑倒，顺手扶了一下。”他眼神很直。“我满脑子都是带子能不能转。你在水房，我想喊你，你转身走了。”</p><p>我脸一热。“我当时气得手抖，热水溅出来都没觉得疼。”</p><p>“赵晴跟你说的，对吗。”</p><p>“嗯。她也是担心我。”我把瓶子换到另一边抱着，手臂发酸。“我一听旧磁带，一人一只耳机，脑子就乱了。那盘带子你只放给我听过，我以为……”</p><p>“以为我分给别人了。”他接过去，语气很轻，没有责怪，像在替我说完。“傻不傻。分得清的东西很多，分不清的就问我。我嘴笨，可你问，我一定说实话。”</p><p>走到第五圈，雾薄了一点。场边的灯亮起来，光晕散开，照着跑道上的水珠，一闪一闪。我的喘平了，步子也稳了。汗从后颈渗出来，被风一吹，凉飕飕。</p><p>“门口打断你，生气了吗。”我问。</p><p>“生了一会。”他点头。“气你不听，也气自己没说清。陈默骂我讲得太硬。”</p><p>我眼眶发热，又想笑。“那现在讲故事吧。”</p><p>他想了想，忽然问：“瓶里的星星，你数了吗。”</p><p>“数了。林小满说少了最亮的一颗。”我把瓶子举起来晃晃。纸星星哗啦响，粉的黄的蓝的翻滚，确实空了一小块。“你藏哪去了。”</p><p>他没回答，只是问：“走了几圈了。”</p><p>“八圈了吧。”</p><p>“记性不错。”他从外套内兜摸出一颗纸星星。那颗很大，纸面撒着细闪，在灯下亮晶晶。他捏着星角，在我眼前晃。“这颗我拿走了，昨晚叠的，纸都快被我捏潮了。”</p><p>“为什么拿走。”</p><p>“因为想跟你说话，又怕你不想见我。”他把星星放回我掌心。纸面还带着他的体温，暖暖的。“我想着，走圈的时候还你，当面还。”</p><p>星角硌着掌心，疼又安心。我攥紧星星，鼻子发酸。</p><p>“那句不想见，是气话。”</p><p>“我知道。”他点头。“你说想退一下，我就原地等。可你退太远，我会慌。”</p><p>第十圈过半，腿开始发沉。雾水落在睫毛上，看东西蒙蒙的。场外小卖部关门声响过，又静下去，只剩一点烤红薯的甜香，一丝一缕。</p><p>“那你慌的时候怎么办。”我问。</p><p>“叠星星，听带子。”他笑了一下，露出一点疲惫。“那晚我叠到半夜，指头都疼了。旧磁带听了一遍又一遍，海浪声里全是你的哼唱。我还多录了一段。”</p><p>我的心跳快起来。“林小满说，你的带子里多了一段我没听过的哼唱。”</p><p>“嗯。”他卖了个关子。“走完再给你听。”</p><p>“耍赖。”我瞪他，又忍不住笑。雾气吸进肺里，凉凉的，带着青草被踩碎后的清苦。</p><p>第十三圈，风小了。步子合到一起，影子在灯下拖得很长，时而分开，时而叠在一起。</p><p>“赵晴传岔了，你怪她吗。”他问。</p><p>“不怪。”我摇头，发梢扫到脸颊，有点痒。“她手很暖，也是怕我被蒙住。林小满也好，给糖又借外套。”</p><p>“那我呢。”他停下来，很认真地看我。“你怕我吗。怕问了，听到不想听的。”</p><p>我也停下来。跑道上的水洼映着灯，亮亮一小片。我的倒影晃动，显得很小。</p><p>“怕。”我说得很慢。“越在意，越怕。你晃星星瓶来找我时，我委屈得想哭。你明明对我笑，转头又对别人笑。我知道这样想很小气，可忍不住。”</p><p>他听完，伸手轻轻碰了一下我的袖口，又收回去，很克制。</p><p>“那以后换我来问。”他说。“你冷脸，我就问。你躲，我就等。等不到，我就来操场走圈，走到你肯来为止。”</p><p>“二十圈，腿不酸吗。”</p><p>“酸。”他迈步示意我跟上。“走着走着，气就顺了。现在第几圈。”</p><p>“第十六圈。”</p><p>“还剩四圈，够说正事。”他摸出两颗海盐糖，剥开一颗递给我。“宋阿婆说的，心慌含一颗。”</p><p>糖进嘴，先咸后甜，腿上的酸胀轻了一点。</p><p>“正事是什么。”</p><p>“第一件，磁带的事翻篇了，以后有转交的带子，我当着你的面试。”</p><p>“好。”</p><p>“第二件，星星瓶满了，带你去海边听潮。退潮时去，潮声稳，不吓人。”</p><p>“好。”我把那颗最亮的星星举起来，对着灯看。光透过纸面，暖暖的。“第三件呢。”</p><p>他没说话，只是从怀里掏出随身听。旧机子边角磨白了，标签上是我的小字。他把耳机分我一只，耳棉软软的，带着一点他的温度。</p><p>“第三件，听带子。”</p><p>第二十圈终点就在脚下。白线湿了，凉意透过鞋底。场上很静，能听见彼此的呼吸，和远处潮声叠在一起。</p><p>他按下播放键，咔哒一声。杂音过后，海浪声涌出来，一层一层。我的哼唱在里面，很轻，跑调的地方都没变。</p><p>我听得眼热，正想笑他录我跑调，一段新的哼唱浮出来。</p><p>那是他的声音。很低，有点哑，学着我的调子，慢半拍，却很稳。唱到尾，他停了，潮声里留了一句很轻的话。</p><p>他说，退潮也会回来，星星少一颗也会补上，你退一下，我走二十圈去接你。</p><p>耳机里潮声未歇，雾落在我们肩上，细细一层水。我攥着那颗最亮的星星，抬头看他，喉咙哽得说不出话。</p><p>他把另一只耳机摘下来，很郑重地放回我手心，忽然朝场边看了一眼，神色变了。</p><p>“别回头。”他压低声音。“场边站着的人，从第十圈就一直在看我们，手里好像拿着你的东西。”</p>',79)])])}const f=e(o,[["render",r]]);export{m as __pageData,f as default};
